#include <unistd.h>
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <string.h>
#include <fcntl.h>
#include <sys/uio.h>
int main(int argc, char **argv) {
    pid_t pid = fork();
    if (pid == 0) {
        // child: execute target with harmless args
        // We want to keep child alive for dump
        // Use sleep?
        char *args[] = {"/workspace/executable", "-h", NULL};
        execv("/workspace/executable", args);
        perror("execv");
        exit(1);
    } else {
        // parent: wait a bit, then try to read /proc/pid/exe
        sleep(1);
        char path[256];
        snprintf(path, sizeof(path), "/proc/%d/exe", pid);
        char buf[1024];
        ssize_t len = readlink(path, buf, sizeof(buf)-1);
        if (len != -1) {
            buf[len] = '\0';
            printf("exe link: %s\n", buf);
        } else perror("readlink");
        // Try to open /proc/pid/exe for reading
        int fd = open(path, O_RDONLY);
        if (fd < 0) perror("open exe");
        else {
            printf("opened exe fd %d\n", fd);
            // Try to copy
            FILE *out = fopen("/tmp/dumped", "wb");
            if (!out) perror("fopen out");
            else {
                char buffer[4096];
                ssize_t n;
                while ((n = read(fd, buffer, sizeof(buffer))) > 0) {
                    fwrite(buffer, 1, n, out);
                }
                fclose(out);
                printf("dumped to /tmp/dumped\n");
            }
            close(fd);
        }
        // Also try /proc/pid/maps
        snprintf(path, sizeof(path), "/proc/%d/maps", pid);
        FILE *maps = fopen(path, "r");
        if (maps) {
            char line[512];
            while (fgets(line, sizeof(line), maps)) {
                printf("maps: %s", line);
            }
            fclose(maps);
        }
        // Kill child
        kill(pid, 9);
        waitpid(pid, NULL, 0);
    }
    return 0;
}
EOF
