import subprocess, os, tempfile, shutil, textwrap, json, time

def run_wrap(code, config=None):
    tmp = tempfile.mkdtemp()
    os.makedirs(os.path.join(tmp, "foo"))
    open(os.path.join(tmp, "go.mod"), "w").write("module example.com/foo

go 1.21
")
    open(os.path.join(tmp, "foo", "foo.go"), "w").write(code)
    if config:
        open(os.path.join(tmp, ".wrapcheck.yaml"), "w").write(config)
    proc = subprocess.run(["/workspace/executable", "-json", "./..."], cwd=tmp, capture_output=True, text=True, timeout=10)
    out = proc.stdout.strip()
    flagged = '"posn"' in out
    # also plain
    proc2 = subprocess.run(["/workspace/executable", "./..."], cwd=tmp, capture_output=True, text=True, timeout=10)
    plain = proc2.stderr.strip()
    print(f"flagged={flagged} plain>{plain[:80]}< code:{code[:70].replace(chr(10),'|')}")
    shutil.rmtree(tmp, ignore_errors=True)
    time.sleep(0.2)
    return flagged

# Test various returns
cases = [
    ("direct return", 'func Foo() error {
    _, err := os.Open("x")
    return err
}'),
    ("direct return inside if", 'func Foo() error {
    _, err := os.Open("x")
    if err != nil { return err }
    return nil
}'),
    ("copy then return", 'func Foo() error {
    _, err := os.Open("x")
    err2 := err
    return err2
}'),
    ("copy inside if then return", 'func Foo() error {
    _, err := os.Open("x")
    if err != nil { err2 := err; return err2 }
    return nil
}'),
    ("copy via var", 'func Foo() error {
    _, err := os.Open("x")
    var e = err
    return e
}'),
    ("reassign err then return", 'func Foo() error {
    _, err := os.Open("x")
    err = err
    return err
}'),
    ("wrapped direct", 'func Foo() error {
    _, err := os.Open("x")
    if err != nil { return fmt.Errorf("w: %w", err) }
    return nil
}'),
    ("wrapped via var then return copy", 'func Foo() error {
    _, err := os.Open("x")
    if err != nil { w := fmt.Errorf("w: %w", err); e := w; return e }
    return nil
}'),
    ("wrapped via err reassign", 'func Foo() error {
    _, err := os.Open("x")
    if err != nil { err = fmt.Errorf("w: %w", err); return err }
    return nil
}'),
    ("internal helper direct", 'func Helper() error { return os.ErrNotExist }
func Foo() error {
    err := Helper()
    return err
}'),
    ("internal helper copy", 'func Helper() error { return os.ErrNotExist }
func Foo() error {
    err := Helper()
    err2 := err
    return err2
}'),
]

for name, body in cases:
    code = f"package foo
