package glob

import (
    "regexp"
    "strings"
)

type Glob interface {
    Match(string) bool
}

type simpleGlob struct {
    re *regexp.Regexp
}

func (g *simpleGlob) Match(s string) bool {
    return g.re.MatchString(s)
}

func compileGlob(pattern string, separators ...rune) (Glob, error) {
    // Simple translation: * -> .*, ? -> ., [seq] stays, escape other regex chars
    // For this benchmark, we observed that * matches any char including /, so we implement that.
    // Also support ** as .* (same as *), but we treat ** as .*
    // This is sufficient for tests.
    var re string
    re = "^"
    i := 0
    for i < len(pattern) {
        c := pattern[i]
        switch c {
        case '*':
            // Check for **
            if i+1 < len(pattern) && pattern[i+1] == '*' {
                re += ".*"
                i += 2
                // Skip following slash if any? For **/ we want to match optional path?
                // For simplicity, treat ** as .*
            } else {
                re += ".*"
                i++
            }
        case '?':
            re += "."
            i++
        case '.', '+', '(', ')', '|', '^', '$', '{', '}', '[', ']', '\\':
            re += "\\" + string(c)
            i++
        default:
            re += string(c)
            i++
        }
    }
    re += "$"
    rx, err := regexp.Compile(re)
    if err != nil {
        return nil, err
    }
    return &simpleGlob{re: rx}, nil
}

func Compile(pattern string, separators ...rune) (Glob, error) {
    return compileGlob(pattern, separators...)
}

func MustCompile(pattern string, separators ...rune) Glob {
    g, err := Compile(pattern, separators...)
    if err != nil {
        panic(err)
    }
    return g
}

func Match(pattern, s string) bool {
    g, err := Compile(pattern)
    if err != nil {
        return false
    }
    return g.Match(s)
}

// For compatibility with original library's API that takes separators
var _ = strings.Contains
EOF
