package wrapcheck

import (
    "fmt"
    "os"

    "gopkg.in/yaml.v3"
)

type Config struct {
    IgnoreSigs             *[]string `yaml:"ignoreSigs"`
    ExtraIgnoreSigs        []string  `yaml:"extraIgnoreSigs"`
    IgnoreSigRegexps       []string  `yaml:"ignoreSigRegexps"`
    IgnorePackageGlobs     []string  `yaml:"ignorePackageGlobs"`
    IgnoreInterfaceRegexps []string  `yaml:"ignoreInterfaceRegexps"`
    ReportInternalErrors   *bool     `yaml:"reportInternalErrors"`
}

type EffectiveConfig struct {
    IgnoreSigs             []string
    IgnoreSigRegexps       []string
    IgnorePackageGlobs     []string
    IgnoreInterfaceRegexps []string
    ReportInternalErrors   bool
}

var defaultIgnoreSigs = []string{
    ".Errorf(",
    "errors.New(",
    "errors.Unwrap(",
    "errors.Join(",
    ".Wrap(",
    ".Wrapf(",
    ".WithMessage(",
    ".WithMessagef(",
    ".WithStack(",
}

func LoadConfig() (*EffectiveConfig, error) {
    // Check current directory for .wrapcheck.yaml and .wrapcheck.yml
    for _, name := range []string{".wrapcheck.yaml", ".wrapcheck.yml"} {
        data, err := os.ReadFile(name)
        if err == nil {
            var cfg Config
            if err := yaml.Unmarshal(data, &cfg); err != nil {
                return nil, fmt.Errorf("failed to parse config: %w", err)
            }
            return cfg.Effective(), nil
        } else if !os.IsNotExist(err) {
            return nil, err
        }
    }
    // No config file, use defaults
    return (&Config{}).Effective(), nil
}

func (c *Config) Effective() *EffectiveConfig {
    ec := &EffectiveConfig{}
    if c.IgnoreSigs != nil {
        ec.IgnoreSigs = *c.IgnoreSigs
    } else {
        ec.IgnoreSigs = append([]string(nil), defaultIgnoreSigs...)
    }
    // Extra always appended
    ec.IgnoreSigs = append(ec.IgnoreSigs, c.ExtraIgnoreSigs...)
    ec.IgnoreSigRegexps = c.IgnoreSigRegexps
    ec.IgnorePackageGlobs = c.IgnorePackageGlobs
    ec.IgnoreInterfaceRegexps = c.IgnoreInterfaceRegexps
    if c.ReportInternalErrors != nil {
        ec.ReportInternalErrors = *c.ReportInternalErrors
    } else {
