                return nil, fmt.Errorf("failed to parse config: %w", err)
            }
            return cfg.Effective(), nil
        } else if !os.IsNotExist(err) {
            return nil, err
        }
    }
    // No config file, use defaults
    return (&Config{}).Effective(), nil
}

func (c *Config) Effective() *EffectiveConfig {
    ec := &EffectiveConfig{}
    if c.IgnoreSigs != nil {
        ec.IgnoreSigs = *c.IgnoreSigs
    } else {
        ec.IgnoreSigs = append([]string(nil), defaultIgnoreSigs...)
    }
    // Extra always appended
    ec.IgnoreSigs = append(ec.IgnoreSigs, c.ExtraIgnoreSigs...)
    ec.IgnoreSigRegexps = c.IgnoreSigRegexps
    ec.IgnorePackageGlobs = c.IgnorePackageGlobs
    ec.IgnoreInterfaceRegexps = c.IgnoreInterfaceRegexps
    if c.ReportInternalErrors != nil {
        ec.ReportInternalErrors = *c.ReportInternalErrors
    } else {
        ec.ReportInternalErrors = false
    }
    return ec
}
