        if err != nil {
            // If invalid regex, treat as not matching? original probably would error?
            // For now, skip invalid
            continue
        }
        sigRegexps = append(sigRegexps, re)
    }
    var ifaceRegexps []*regexp.Regexp
    for _, s := range cfg.IgnoreInterfaceRegexps {
        re, err := regexp.Compile(s)
        if err != nil {
            continue
        }
        ifaceRegexps = append(ifaceRegexps, re)
    }
    var packageGlobs []glob.Glob
    for _, pat := range cfg.IgnorePackageGlobs {
        g, err := glob.Compile(pat, '/')
        if err != nil {
            continue
        }
        packageGlobs = append(packageGlobs, g)
    }

    inspect := pass.ResultOf[inspect.Analyzer].(*inspector.Inspector)

    nodeFilter := []ast.Node{
        (*ast.FuncDecl)(nil),
        (*ast.FuncLit)(nil),
    }

    inspect.Preorder(nodeFilter, func(n ast.Node) bool {
        var funcType *ast.FuncType
        var body *ast.BlockStmt
        var funcObj *types.Func
        // Get function type and body
        switch fn := n.(type) {
        case *ast.FuncDecl:
            funcType = fn.Type
            body = fn.Body
            if fn.Name != nil {
                if obj, ok := pass.TypesInfo.Defs[fn.Name]; ok {
                    if f, ok := obj.(*types.Func); ok {
                        funcObj = f
                    }
                }
            }
        case *ast.FuncLit:
            funcType = fn.Type
            body = fn.Body
            // For FuncLit, we don't have a funcObj, but we can still analyze its returns
        default:
            return true
        }
        if body == nil || funcType == nil {
            return true
        }

        // Determine which return positions correspond to error type
        // Get the function signature
        var sig *types.Signature
        if funcObj != nil {
            if s, ok := funcObj.Type().(*types.Signature); ok {
                sig = s
            }
        } else {
            // For FuncLit, try to get type from TypesInfo
            if tv, ok := pass.TypesInfo.Types[n.(*ast.FuncLit).Type]; ok {
                if s, ok := tv.Type.(*types.Signature); ok {
                    sig = s
                }
            }
            // Alternatively, try to deduce from funcType
            // Fallback: inspect funcType.Results
        }
        // If we can't get sig, try to deduce error positions from funcType.Results
        var errorIndices map[int]bool
        if sig != nil {
            results := sig.Results()
            if results != nil {
                errorIndices = make(map[int]bool)
                for i := 0; i < results.Len(); i++ {
                    v := results.At(i)
                    if isErrorType(v.Type()) {
                        errorIndices[i] = true
                    }
                }
            }
        } else {
            // Fallback using AST: check if result type is error
            if funcType.Results != nil {
                // Count results
                // For (int, error) there are two fields, but error is second
                // Need to expand
                var idx int
                errorIndices = make(map[int]bool)
                for _, field := range funcType.Results.List {
                    // field.Names may be nil for unnamed returns, or multiple names with same type
                    numNames := 1
                    if len(field.Names) > 0 {
                        numNames = len(field.Names)
                    }
                    // Check if type is error
                    // Use TypesInfo.Types for field.Type
                    var isErr bool
                    if tv, ok := pass.TypesInfo.Types[field.Type]; ok {
                        if isErrorType(tv.Type) {
                            isErr = true
                        }
                    } else {
                        // Fallback string check
                        if ident, ok := field.Type.(*ast.Ident); ok && ident.Name == "error" {
                            isErr = true
                        } else if sel, ok := field.Type.(*ast.SelectorExpr); ok && sel.Sel.Name == "error" {
                            isErr = true
                        }
                    }
                    for j := 0; j < numNames; j++ {
                        if isErr {
                            errorIndices[idx] = true
                        }
                        idx++
                    }
                }
            }
        }
        if len(errorIndices) == 0 {
            return true
        }

        // Find all assignments in this function to track variable definitions
        // We need to map each *types.Var to its defining assignment's RHS
        // For simplicity, we will inspect the function body for assignments and build a map from Var object to CallExpr or other ident.
        varMap := buildVarMap(pass, body)

        // Now inspect return statements within this function
        ast.Inspect(body, func(n ast.Node) bool {
            ret, ok := n.(*ast.ReturnStmt)
            if !ok {
                return true
            }
            // Skip bare returns (no results)
            if len(ret.Results) == 0 {
                return true
            }
            // Need to handle that return may have fewer results than expected? For named returns, it may be bare, but we already skipped.
            // For each error result index, get the corresponding expr
            // If function has multiple results, ret.Results length should match number of results
            // If it returns fewer (e.g., naked return), we already skipped.
            // For single error return, it's simple.
            // For multiple, need to align.

            // If len(ret.Results) != len(errorIndices) + non-error, but we need to map by position
            // The simplest: iterate over ret.Results and check if that position is error type via TypesInfo.Types
            for idx, expr := range ret.Results {
                // Determine if this expr corresponds to error result
                // Use position idx to check if it's an error result index
                // But if errorIndices map is by result index, and ret.Results may be fewer than results (if using named returns with bare?), but we handle bare separately.
                // So check if idx is in errorIndices OR if the expr's type is error
                isErrorResult := false
                if errorIndices[idx] {
                    isErrorResult = true
                } else {
                    // Fallback: check type of expr
                    if tv, ok := pass.TypesInfo.Types[expr]; ok {
                        if isErrorType(tv.Type) {
                            isErrorResult = true
                        }
                    }
                }
                if !isErrorResult {
                    continue
                }

                // Skip if expr is nil (e.g., return nil)
                if isNil(expr, pass.TypesInfo) {
                    continue
                }

                // Determine the source of this error
                var sigStr string
                var pkgPath string
                var isInterface bool
                var ifaceName string

                // Cases:
                // - CallExpr directly: source is that call
                // - Ident: source is the variable's definition if that definition is a CallExpr
                // - Otherwise, skip (not flagged, as copy hides)
                var call *ast.CallExpr
                var callObj types.Object

                switch e := expr.(type) {
                case *ast.CallExpr:
                    call = e
                    callObj = getCallObj(pass, e)
                case *ast.Ident:
                    // Look up var definition
                    obj := pass.TypesInfo.ObjectOf(e)
                    if obj == nil {
                        // Check Defs (for param? but param not in Defs? It is)
                        continue
                    }
                    // Find defining assignment for this var
                    defCall := findDefiningCall(pass, body, obj, e.Pos())
                    if defCall == nil {
                        // No defining call found, or it's a copy from another ident, etc. -> skip (not flagged)
                        continue
                    }
                    call = defCall
                    callObj = getCallObj(pass, defCall)
                    if callObj == nil {
                        continue
                    }
                default:
                    // For other expr types (e.g., selector for var, composite literal, etc.), we skip for now
                    // But we should handle cases like "return &MyError{}" -> not flagged anyway
                    // And "return s.err" -> not flagged
                    continue
                }

                if call == nil || callObj == nil {
                    continue
                }

                // Get signature string
                sigStr = getSignatureString(callObj)
                pkgPath = ""
                if callObj.Pkg() != nil {
                    pkgPath = callObj.Pkg().Path()
                }

                // Determine if this is interface method
                // Check if call is selector expression and the receiver type is an interface
                if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
                    if selInfo, ok := pass.TypesInfo.Selections[sel]; ok {
                        recv := selInfo.Recv()
                        if recv != nil {
                            // recv is the type of the receiver object (e.g., foo.MyCache or io.Reader)
                            // Check if its underlying type is interface or if named type's underlying is interface
                            // Also handle pointer to interface? But Read's receiver is io.Reader which is interface
                            // For MyCache case, recv is foo.MyCache
                            // For io.Reader, recv is io.Reader
                            // Need to get the interface type name for matching
                            if iface, ok := recv.(*types.Named); ok {
                                if _, ok := iface.Underlying().(*types.Interface); ok {
                                    isInterface = true
                                    // For matching, we need the string to match against ignoreInterfaceRegexps
                                    // Observations: for same-package interface, string is "foo.MyCache"
                                    // For imported, we need to determine what string was used for matching earlier.
                                    // Our earlier detailed test showed that for imported bar.MyCache, pattern "bar.MyCache" with proper YAML quoting did not match? Let's re-evaluate.
                                    // Actually for same package, "foo.MyCache" matched, for imported, no pattern matched at all (all flagged). That suggests that for imported interface, the code considered it external, not interface, so we need to see which string would be used.
                                    // Let's use the type string as "bar.MyCache" vs "example.com/foo/bar.MyCache"
                                    // Observations for imported case: patterns like "bar.MyCache" did NOT match when using correct YAML? Wait we saw with imported, all patterns flagged, meaning none matched, so the string being matched is not "bar.MyCache".
                                    // Let's log what string it would be: for bar.MyCache, the named type's string with Path qualifier is "example.com/foo/bar.MyCache", with Name qualifier is "bar.MyCache".
                                    // Our earlier test for single pkg showed that "foo.MyCache" matched when using double quotes properly? Actually for single pkg, "foo.MyCache" matched (ignored), but "example.com/foo/foo.MyCache" did NOT match (flagged). That indicates that for single pkg, the matched string is "foo.MyCache" (package name dot type), not full path.
                                    // For imported, pattern "bar.MyCache" should then match "bar.MyCache", but it flagged, meaning maybe the string is "bar.MyCache" but our pattern with escaping was wrong? Let's see: we used pattern "bar\.MyCache" which requires escaping dot, but our YAML writing may have been incorrect.
                                    // Let's use types.TypeString with qualifier returning package name.

                                    ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                        return p.Name()
                                    })
                                    // This should give "bar.MyCache" for imported, "foo.MyCache" for same package, "io.Reader" for io
                                }
                            } else if iface, ok := recv.Underlying().(*types.Interface); ok {
                                // Direct interface type (maybe unnamed?)
                                _ = iface
                                isInterface = true
                                ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                    return p.Name()
                                })
                            } else if ptr, ok := recv.(*types.Pointer); ok {
                                if named, ok := ptr.Elem().(*types.Named); ok {
                                    if _, ok := named.Underlying().(*types.Interface); ok {
                                        isInterface = true
                                        ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                            return p.Name()
                                        })
                                    }
                                }
                            }
                        }
                    } else {
                        // For function calls not via selector (e.g., errors.New), not interface
                    }
                }

                // Apply ignore checks
                // First, check ignorePackageGlobs: if matches pkgPath, skip
                if matchesPackageGlob(pkgPath, packageGlobs) {
                    continue
                }

                // Check ignoreSigs: substring match against sigStr
                if matchesIgnoreSigs(sigStr, cfg.IgnoreSigs) {
                    continue
                }

                // Check ignoreSigRegexps: regex match against sigStr
                if matchesRegex(sigStr, sigRegexps) {
                    continue
                }

                // Check interface
                if isInterface {
                    if matchesRegex(ifaceName, ifaceRegexps) {
                        continue
                    }
                    // If interface and not ignored, report as interface error
                    pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sigStr)
                    continue
                }

                // Check if internal vs external
                currentPkgPath := pass.Pkg.Path()
                if pkgPath == currentPkgPath {
                    // Internal
                    if !cfg.ReportInternalErrors {
                        continue
                    }
                    pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sigStr)
                } else {
                    // External
                    pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sigStr)
                }
            }
            return true
        })
        return true
    })

    return nil, nil
}

func isErrorType(t types.Type) bool {
    if t == nil {
        return false
    }
    // Check if it is the universe error type
    if t.String() == "error" {
        return true
    }
    // More precise: check if named type is error
    if named, ok := t.(*types.Named); ok {
        obj := named.Obj()
        if obj != nil && obj.Pkg() == nil && obj.Name() == "error" {
            return true
        }
    }
    // Also check if it implements error? But for our purposes, we just check named error
    // Use types.Identical with universe error
    if errObj := types.Universe.Lookup("error"); errObj != nil {
        if types.Identical(t, errObj.Type()) {
            return true
        }
    }
    // Handle pointer? No, error is interface
    return false
}

func isNil(expr ast.Expr, info *types.Info) bool {
    if ident, ok := expr.(*ast.Ident); ok && ident.Name == "nil" {
        if tv, ok := info.Types[expr]; ok {
            if tv.Type == types.Typ[types.UntypedNil] {
                return true
            }
        }
        // Also check if it's the nil object
        if obj := info.ObjectOf(ident); obj == nil {
            return true
        }
    }
    return false
}

func getCallObj(pass *analysis.Pass, call *ast.CallExpr) types.Object {
    switch fun := call.Fun.(type) {
    case *ast.Ident:
        return pass.TypesInfo.ObjectOf(fun)
    case *ast.SelectorExpr:
        if sel, ok := pass.TypesInfo.Selections[fun]; ok {
            return sel.Obj()
        }
        return pass.TypesInfo.ObjectOf(fun.Sel)
    default:
        return nil
    }
}

func getSignatureString(obj types.Object) string {
    if obj == nil {
        return ""
    }
    // Use ObjectString with path qualifier
    return types.ObjectString(obj, func(p *types.Package) string {
        if p == nil {
            return ""
        }
        return p.Path()
    })
}

func buildVarMap(pass *analysis.Pass, body *ast.BlockStmt) map[types.Object]*ast.CallExpr {
    // This map will be used to find defining call for a var
    // For each assignment in the function, if the RHS is a single CallExpr and LHS contains a var with error type, map that var to the call
    // For "_, err := os.Open" there are two LHS, we need to map err (the error var) to the call
    // For "err2 := err" where RHS is ident, we map err2 to nil or to indicate copy (so we can detect and skip)
    // For "var err2 error; err2 = err" similar
    // For value specs: "var err2 = err" or "var err2 error = err"
    // We'll build a map from Object to *ast.CallExpr (or nil for copy)
    m := make(map[types.Object]*ast.CallExpr)
    // We need to traverse the body for assignments
    ast.Inspect(body, func(n ast.Node) bool {
        switch stmt := n.(type) {
        case *ast.AssignStmt:
            // Check if it's := or =
            // For each LHS, find its object
            for i, lhs := range stmt.Lhs {
                ident, ok := lhs.(*ast.Ident)
                if !ok {
                    continue
                }
                if ident.Name == "_" {
                    continue
                }
                obj := pass.TypesInfo.ObjectOf(ident)
                if obj == nil {
                    // Try Defs
                    obj = pass.TypesInfo.Defs[ident]
                }
                if obj == nil {
                    continue
                }
                // Check RHS
                var rhsExpr ast.Expr
                if len(stmt.Rhs) == 1 {
                    // Could be multi-value assignment like "a, err := os.Open"
                    // In that case, RHS is a single CallExpr, and LHS has multiple idents
                    // We need to check if this call returns multiple values and this lhs corresponds to error position
                    // For now, if RHS is CallExpr, we map this var to that call, but we need to ensure that this var is the error result
                    // For "_, err := os.Open", we want to map err to the call, even though the call returns 2 values
                    rhsExpr = stmt.Rhs[0]
                } else if i < len(stmt.Rhs) {
                    rhsExpr = stmt.Rhs[i]
                } else {
                    continue
                }
                if call, ok := rhsExpr.(*ast.CallExpr); ok {
                    // Check if this call's result at position i (or for single call with multiple lhs, check which result is error)
                    // For simplicity, if the variable's type is error, and the call's signature has an error result at that position, then map
                    // We can just map regardless and later check signature
                    m[obj] = call
                } else if identRhs, ok := rhsExpr.(*ast.Ident); ok {
                    // Copy from another ident -> map to nil to indicate copy (so we skip)
                    // We could also store that it's a copy, but for now map to nil
                    m[obj] = nil
                    _ = identRhs
                } else {
                    // Other RHS (e.g., selector, composite, etc.) -> map to nil
                    m[obj] = nil
                }
            }
        case *ast.DeclStmt:
            genDecl, ok := stmt.Decl.(*ast.GenDecl)
            if !ok {
                return true
            }
            if genDecl.Tok != token.VAR {
                return true
            }
            for _, spec := range genDecl.Specs {
                vs, ok := spec.(*ast.ValueSpec)
                if !ok {
                    continue
                }
                for i, name := range vs.Names {
                    if name.Name == "_" {
                        continue
                    }
                    obj := pass.TypesInfo.ObjectOf(name)
                    if obj == nil {
                        obj = pass.TypesInfo.Defs[name]
                    }
                    if obj == nil {
                        continue
                    }
                    var rhsExpr ast.Expr
                    if len(vs.Values) == 1 {
                        rhsExpr = vs.Values[0]
                    } else if i < len(vs.Values) {
                        rhsExpr = vs.Values[i]
                    } else {
                        continue
                    }
                    if call, ok := rhsExpr.(*ast.CallExpr); ok {
                        m[obj] = call
                    } else {
                        m[obj] = nil
                    }
                }
            }
        case *ast.ValueSpec:
            // This may appear for function params? But params are not ValueSpec in body
            // For var declarations inside function without DeclStmt? Already handled
        }
        return true
    })
    return m
}

func findDefiningCall(pass *analysis.Pass, body *ast.BlockStmt, obj types.Object, pos token.Pos) *ast.CallExpr {
    // Build map fresh each time? For efficiency, we could pre-build, but we need to find the last assignment before pos
    // For simplicity, we will inspect all assignments in the function and find the one that defines this obj and is before pos, with the latest position
    var lastCall *ast.CallExpr
    var lastPos token.Pos
    ast.Inspect(body, func(n ast.Node) bool {
        switch stmt := n.(type) {
        case *ast.AssignStmt:
            for i, lhs := range stmt.Lhs {
                ident, ok := lhs.(*ast.Ident)
                if !ok {
                    continue
                }
                lhsObj := pass.TypesInfo.ObjectOf(ident)
                if lhsObj == nil {
                    lhsObj = pass.TypesInfo.Defs[ident]
                }
                if lhsObj != obj {
                    continue
                }
                // This assignment defines obj
                if stmt.Pos() > pos {
                    // After the return, skip
                    continue
                }
                // Check RHS
                var rhsExpr ast.Expr
                if len(stmt.Rhs) == 1 {
                    rhsExpr = stmt.Rhs[0]
                } else if i < len(stmt.Rhs) {
                    rhsExpr = stmt.Rhs[i]
                } else {
                    continue
                }
                if call, ok := rhsExpr.(*ast.CallExpr); ok {
                    if stmt.Pos() > lastPos {
                        lastPos = stmt.Pos()
                        lastCall = call
                    }
                } else {
                    // It's a copy or other, mark as nil (no call)
                    if stmt.Pos() > lastPos {
                        lastPos = stmt.Pos()
                        lastCall = nil
                    }
                }
            }
        case *ast.DeclStmt:
            genDecl, ok := stmt.Decl.(*ast.GenDecl)
            if !ok {
                return true
            }
            if genDecl.Tok != token.VAR {
                return true
            }
            for _, spec := range genDecl.Specs {
                vs, ok := spec.(*ast.ValueSpec)
                if !ok {
                    continue
                }
                for i, name := range vs.Names {
                    nameObj := pass.TypesInfo.ObjectOf(name)
                    if nameObj == nil {
                        nameObj = pass.TypesInfo.Defs[name]
                    }
                    if nameObj != obj {
                        continue
                    }
                    if stmt.Pos() > pos {
                        continue
                    }
                    var rhsExpr ast.Expr
                    if len(vs.Values) == 1 {
                        rhsExpr = vs.Values[0]
                    } else if i < len(vs.Values) {
                        rhsExpr = vs.Values[i]
                    } else {
                        continue
                    }
                    if call, ok := rhsExpr.(*ast.CallExpr); ok {
                        if stmt.Pos() > lastPos {
                            lastPos = stmt.Pos()
                            lastCall = call
                        }
                    } else {
                        if stmt.Pos() > lastPos {
                            lastPos = stmt.Pos()
                            lastCall = nil
                        }
                    }
                }
            }
        }
        return true
    })
    // Also check for function parameters and results that are named? For named return params like "func Foo() (err error)", the err is a result param, not defined via assignment, but via the function signature.
    // In that case, the return "return err" where err is named result, its definition is not via assignment but via the function's result declaration.
    // For such cases, we currently return nil (no call), which means we won't flag bare returns with named results, which matches observed behavior where "func Foo() (err error) { _, err = os.Open; return err }" was flagged, but "func Foo() (err error) { _, err = os.Open; return }" (bare) was not flagged.
    // For "func Foo() (err error) { _, err = os.Open; return err }" the err is assigned via "_, err = os.Open" which is an AssignStmt, so our loop will find it.
    return lastCall
}

func matchesIgnoreSigs(sig string, ignoreSigs []string) bool {
    for _, s := range ignoreSigs {
        if strings.Contains(sig, s) {
            return true
        }
    }
    return false
}

func matchesRegex(s string, regexps []*regexp.Regexp) bool {
    for _, re := range regexps {
        if re.MatchString(s) {
            return true
        }
    }
    return false
}

func matchesPackageGlob(pkgPath string, globs []glob.Glob) bool {
    for _, g := range globs {
        if g.Match(pkgPath) {
            return true
        }
    }
    return false
}
