package glob

import (
    "regexp"
    "strings"
)

type Glob interface {
    Match(string) bool
}

type simpleGlob struct {
    re *regexp.Regexp
}

func (g *simpleGlob) Match(s string) bool {
    return g.re.MatchString(s)
}

func compileGlob(pattern string, separators ...rune) (Glob, error) {
    var re string
    re = "^"
    i := 0
    for i < len(pattern) {
        c := pattern[i]
        switch c {
        case '*':
            if i+1 < len(pattern) && pattern[i+1] == '*' {
                re += ".*"
                i += 2
            } else {
                re += ".*"
                i++
            }
        case '?':
            re += "."
            i++
        case '.', '+', '(', ')', '|', '^', '$', '{', '}', '[', ']', '\\':
            re += "\\" + string(c)
            i++
        default:
            re += string(c)
            i++
        }
    }
    re += "$"
    rx, err := regexp.Compile(re)
    if err != nil {
        return nil, err
    }
    return &simpleGlob{re: rx}, nil
}

func Compile(pattern string, separators ...rune) (Glob, error) {
    return compileGlob(pattern, separators...)
