                        if recv != nil {
                            if named, ok := recv.(*types.Named); ok {
                                if _, ok := named.Underlying().(*types.Interface); ok {
                                    isInterface = true
                                    ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                        return p.Name()
                                    })
                                }
                            } else if _, ok := recv.Underlying().(*types.Interface); ok {
                                isInterface = true
                                ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                    return p.Name()
                                })
                            } else if ptr, ok := recv.(*types.Pointer); ok {
                                if named, ok := ptr.Elem().(*types.Named); ok {
                                    if _, ok := named.Underlying().(*types.Interface); ok {
                                        isInterface = true
                                        ifaceName = types.TypeString(recv, func(p *types.Package) string {
