                if matchesIgnoreSigs(sigStr, cfg.IgnoreSigs) {
                    continue
                }
                if matchesRegex(sigStr, sigRegexps) {
                    continue
                }
                if isInterface {
                    if matchesRegex(ifaceName, ifaceRegexps) {
                        continue
                    }
                    pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sigStr)
                    continue
                }
                currentPkgPath := pass.Pkg.Path()
                if pkgPath == currentPkgPath {
                    if !cfg.ReportInternalErrors {
                        continue
                    }
                    pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sigStr)
                } else {
                    pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sigStr)
                }
            }
            return true
        })
    })

