package wrapcheck

import (
    "go/ast"
    "go/token"
    "go/types"
    "regexp"
    "strings"

    "github.com/gobwas/glob"
    "golang.org/x/tools/go/analysis"
    "golang.org/x/tools/go/analysis/passes/inspect"
    "golang.org/x/tools/go/ast/inspector"
)

var Analyzer = &analysis.Analyzer{
    Name: "wrapcheck",
    Doc:  "Checks that errors returned from external packages are wrapped",
    Run:  run,
    Requires: []*analysis.Analyzer{
        inspect.Analyzer,
    },
}

func run(pass *analysis.Pass) (interface{}, error) {
    cfg, err := LoadConfig()
    if err != nil {
        return nil, err
    }

    var sigRegexps []*regexp.Regexp
    for _, s := range cfg.IgnoreSigRegexps {
        re, err := regexp.Compile(s)
        if err != nil {
            continue
        }
        sigRegexps = append(sigRegexps, re)
    }
    var ifaceRegexps []*regexp.Regexp
    for _, s := range cfg.IgnoreInterfaceRegexps {
        re, err := regexp.Compile(s)
        if err != nil {
            continue
        }
        ifaceRegexps = append(ifaceRegexps, re)
    }
    var packageGlobs []glob.Glob
    for _, pat := range cfg.IgnorePackageGlobs {
        g, err := glob.Compile(pat, '/')
        if err != nil {
            continue
        }
        packageGlobs = append(packageGlobs, g)
    }

    inspectResult := pass.ResultOf[inspect.Analyzer].(*inspector.Inspector)

    nodeFilter := []ast.Node{
        (*ast.FuncDecl)(nil),
        (*ast.FuncLit)(nil),
    }

    inspectResult.Preorder(nodeFilter, func(n ast.Node) {
        var funcType *ast.FuncType
        var body *ast.BlockStmt
        var funcObj *types.Func
        switch fn := n.(type) {
        case *ast.FuncDecl:
            funcType = fn.Type
            body = fn.Body
            if fn.Name != nil {
                if obj, ok := pass.TypesInfo.Defs[fn.Name]; ok {
                    if f, ok := obj.(*types.Func); ok {
                        funcObj = f
                    }
                }
            }
        case *ast.FuncLit:
            funcType = fn.Type
            body = fn.Body
        default:
            return
        }
        if body == nil || funcType == nil {
            return
        }

        var sig *types.Signature
        if funcObj != nil {
            if s, ok := funcObj.Type().(*types.Signature); ok {
                sig = s
            }
        } else {
            if tv, ok := pass.TypesInfo.Types[n.(*ast.FuncLit).Type]; ok {
                if s, ok := tv.Type.(*types.Signature); ok {
                    sig = s
                }
            }
        }
        var errorIndices map[int]bool
        if sig != nil {
            results := sig.Results()
            if results != nil {
                errorIndices = make(map[int]bool)
                for i := 0; i < results.Len(); i++ {
                    v := results.At(i)
                    if isErrorType(v.Type()) {
                        errorIndices[i] = true
                    }
                }
            }
        } else {
            if funcType.Results != nil {
                var idx int
                errorIndices = make(map[int]bool)
                for _, field := range funcType.Results.List {
                    numNames := 1
                    if len(field.Names) > 0 {
                        numNames = len(field.Names)
                    }
                    var isErr bool
                    if tv, ok := pass.TypesInfo.Types[field.Type]; ok {
                        if isErrorType(tv.Type) {
                            isErr = true
                        }
                    } else {
                        if ident, ok := field.Type.(*ast.Ident); ok && ident.Name == "error" {
                            isErr = true
                        } else if sel, ok := field.Type.(*ast.SelectorExpr); ok && sel.Sel.Name == "error" {
                            isErr = true
                        }
                    }
                    for j := 0; j < numNames; j++ {
                        if isErr {
                            errorIndices[idx] = true
                        }
                        idx++
                    }
                }
            }
        }
        if len(errorIndices) == 0 {
            return
        }

        ast.Inspect(body, func(n ast.Node) bool {
            ret, ok := n.(*ast.ReturnStmt)
            if !ok {
                return true
            }
            if len(ret.Results) == 0 {
                return true
            }
            for idx, expr := range ret.Results {
                isErrorResult := false
                if errorIndices[idx] {
                    isErrorResult = true
                } else {
                    if tv, ok := pass.TypesInfo.Types[expr]; ok {
                        if isErrorType(tv.Type) {
                            isErrorResult = true
                        }
                    }
                }
                if !isErrorResult {
                    continue
                }
                if isNil(expr, pass.TypesInfo) {
                    continue
                }
                var sigStr string
                var pkgPath string
                var isInterface bool
                var ifaceName string
                var call *ast.CallExpr
                var callObj types.Object
                switch e := expr.(type) {
                case *ast.CallExpr:
                    call = e
                    callObj = getCallObj(pass, e)
                case *ast.Ident:
                    obj := pass.TypesInfo.ObjectOf(e)
                    if obj == nil {
                        continue
                    }
                    defCall := findDefiningCall(pass, body, obj, e.Pos())
                    if defCall == nil {
                        continue
                    }
                    call = defCall
                    callObj = getCallObj(pass, defCall)
                    if callObj == nil {
                        continue
                    }
                default:
                    continue
                }
                if call == nil || callObj == nil {
                    continue
                }
                sigStr = getSignatureString(callObj)
                if callObj.Pkg() != nil {
                    pkgPath = callObj.Pkg().Path()
                }
                if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
                    if selInfo, ok := pass.TypesInfo.Selections[sel]; ok {
                        recv := selInfo.Recv()
                        if recv != nil {
                            if named, ok := recv.(*types.Named); ok {
                                if _, ok := named.Underlying().(*types.Interface); ok {
                                    isInterface = true
                                    ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                        return p.Name()
                                    })
                                }
                            } else if _, ok := recv.Underlying().(*types.Interface); ok {
                                isInterface = true
                                ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                    return p.Name()
                                })
                            } else if ptr, ok := recv.(*types.Pointer); ok {
                                if named, ok := ptr.Elem().(*types.Named); ok {
                                    if _, ok := named.Underlying().(*types.Interface); ok {
                                        isInterface = true
                                        ifaceName = types.TypeString(recv, func(p *types.Package) string {
                                            return p.Name()
                                        })
                                    }
                                }
                            }
                        }
                    }
                }
                if matchesPackageGlob(pkgPath, packageGlobs) {
                    continue
                }
                if matchesIgnoreSigs(sigStr, cfg.IgnoreSigs) {
                    continue
                }
                if matchesRegex(sigStr, sigRegexps) {
                    continue
                }
                if isInterface {
                    if matchesRegex(ifaceName, ifaceRegexps) {
                        continue
                    }
                    pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sigStr)
                    continue
                }
                currentPkgPath := pass.Pkg.Path()
                if pkgPath == currentPkgPath {
                    if !cfg.ReportInternalErrors {
                        continue
                    }
                    pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sigStr)
                } else {
                    pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sigStr)
                }
            }
            return true
        })
    })

    return nil, nil
}

func isErrorType(t types.Type) bool {
    if t == nil {
        return false
    }
    if t.String() == "error" {
        return true
    }
    if named, ok := t.(*types.Named); ok {
        obj := named.Obj()
        if obj != nil && obj.Pkg() == nil && obj.Name() == "error" {
            return true
        }
    }
    if errObj := types.Universe.Lookup("error"); errObj != nil {
        if types.Identical(t, errObj.Type()) {
            return true
        }
    }
    return false
}

func isNil(expr ast.Expr, info *types.Info) bool {
    if ident, ok := expr.(*ast.Ident); ok && ident.Name == "nil" {
        if tv, ok := info.Types[expr]; ok {
            if tv.Type == types.Typ[types.UntypedNil] {
                return true
            }
        }
        if obj := info.ObjectOf(ident); obj == nil {
            return true
        }
    }
    return false
}

func getCallObj(pass *analysis.Pass, call *ast.CallExpr) types.Object {
    switch fun := call.Fun.(type) {
    case *ast.Ident:
        return pass.TypesInfo.ObjectOf(fun)
    case *ast.SelectorExpr:
        if sel, ok := pass.TypesInfo.Selections[fun]; ok {
            return sel.Obj()
        }
        return pass.TypesInfo.ObjectOf(fun.Sel)
    default:
        return nil
    }
}

func getSignatureString(obj types.Object) string {
    if obj == nil {
        return ""
    }
    return types.ObjectString(obj, func(p *types.Package) string {
        if p == nil {
            return ""
        }
        return p.Path()
    })
}

func findDefiningCall(pass *analysis.Pass, body *ast.BlockStmt, obj types.Object, pos token.Pos) *ast.CallExpr {
    var lastCall *ast.CallExpr
    var lastPos token.Pos
    ast.Inspect(body, func(n ast.Node) bool {
        switch stmt := n.(type) {
        case *ast.AssignStmt:
            for i, lhs := range stmt.Lhs {
                ident, ok := lhs.(*ast.Ident)
                if !ok {
                    continue
                }
                lhsObj := pass.TypesInfo.ObjectOf(ident)
                if lhsObj == nil {
                    lhsObj = pass.TypesInfo.Defs[ident]
                }
                if lhsObj != obj {
                    continue
                }
                if stmt.Pos() > pos {
                    continue
                }
                var rhsExpr ast.Expr
                if len(stmt.Rhs) == 1 {
                    rhsExpr = stmt.Rhs[0]
                } else if i < len(stmt.Rhs) {
                    rhsExpr = stmt.Rhs[i]
                } else {
                    continue
                }
                if call, ok := rhsExpr.(*ast.CallExpr); ok {
                    if stmt.Pos() > lastPos {
                        lastPos = stmt.Pos()
                        lastCall = call
                    }
                } else {
                    if stmt.Pos() > lastPos {
                        lastPos = stmt.Pos()
                        lastCall = nil
                    }
                }
            }
        case *ast.DeclStmt:
            genDecl, ok := stmt.Decl.(*ast.GenDecl)
            if !ok {
                return true
            }
            if genDecl.Tok != token.VAR {
                return true
            }
            for _, spec := range genDecl.Specs {
                vs, ok := spec.(*ast.ValueSpec)
                if !ok {
                    continue
                }
                for i, name := range vs.Names {
                    nameObj := pass.TypesInfo.ObjectOf(name)
                    if nameObj == nil {
                        nameObj = pass.TypesInfo.Defs[name]
                    }
                    if nameObj != obj {
                        continue
                    }
                    if stmt.Pos() > pos {
                        continue
                    }
                    var rhsExpr ast.Expr
                    if len(vs.Values) == 1 {
                        rhsExpr = vs.Values[0]
                    } else if i < len(vs.Values) {
                        rhsExpr = vs.Values[i]
                    } else {
                        continue
                    }
                    if call, ok := rhsExpr.(*ast.CallExpr); ok {
                        if stmt.Pos() > lastPos {
                            lastPos = stmt.Pos()
                            lastCall = call
                        }
                    } else {
                        if stmt.Pos() > lastPos {
                            lastPos = stmt.Pos()
                            lastCall = nil
                        }
                    }
                }
            }
        }
        return true
    })
    return lastCall
}

func matchesIgnoreSigs(sig string, ignoreSigs []string) bool {
    for _, s := range ignoreSigs {
        if strings.Contains(sig, s) {
            return true
        }
    }
    return false
}

func matchesRegex(s string, regexps []*regexp.Regexp) bool {
    for _, re := range regexps {
        if re.MatchString(s) {
            return true
        }
    }
    return false
}

func matchesPackageGlob(pkgPath string, globs []glob.Glob) bool {
    for _, g := range globs {
        if g.Match(pkgPath) {
            return true
        }
    }
    return false
}
EOF
cat /workspace/wrapcheck/wrapcheck/analyzer.go | head -n 30
"}

